  function dl10Scale() {
    var scales = [[100000, "1 : 100 000"], [200000, "1 : 200 000"], [500000, "1 : 500 000"], [1000000, "1 : 1 000 000"], [250000, "1 : 250 000"]];
    var sc = pick(scales); var cm = rand(2, 9); var km = cm * sc[0] / 100000;
    return mcqQ("Trên bản đồ tỉ lệ " + sc[1] + ", khoảng cách giữa hai điểm đo được " + cm + " cm. Khoảng cách thực tế là bao nhiêu?", [(km * 2) + " km", (km / 2) + " km"], km + " km", cm + " cm × " + sc[0] + " = " + (cm * sc[0]) + " cm = " + km + " km.");
  }
