  function th10Py() {
    var v = rand(0, 2);
    if (v === 0) { var a = rand(2, 9), b = rand(2, 9); return mcqQ("Trong Python, đoạn mã: a = " + a + "; b = " + b + "; print(a * b) in ra kết quả gì?", [String(a + b), String(a * b + 1)], String(a * b), "a * b là phép nhân hai số nguyên."); }
    if (v === 1) { var n = rand(5, 15); var s = n * (n + 1) / 2; return numBlank6("Đoạn mã Python: s = 0; for i in range(1, " + (n + 1) + "): s = s + i. Sau vòng lặp, s bằng bao nhiêu?", "s = ?", s, "Tổng 1 + 2 + … + " + n + " = n(n + 1)/2."); }
    var x = rand(3, 20); return mcqQ("Trong Python, biểu thức " + x + " % 3 (chia lấy dư) cho kết quả gì?", [String((x + 1) % 3), String(Math.floor(x / 3))], String(x % 3), "Toán tử % cho phần dư của phép chia nguyên.");
  }
